type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS: { value: Language; label: string }[] = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'Английский' },
];

export default function ProfileSettingsForm({ onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <form
      className="jx-stack"
      style={{ gap: 'var(--jx-space-4)', maxWidth: '360px' }}
      onSubmit={handleSubmit}
    >
      <div className="jx-field">
        <label className="jx-label" htmlFor="profile-name">
          Имя
        </label>
        <Input
          id="profile-name"
          name="name"
          value={name}
          onChange={(event) => setName(event.target.value)}
          placeholder="Введите имя"
        />
      </div>

      <div className="jx-field">
        <label className="jx-label" htmlFor="profile-language">
          Язык интерфейса
        </label>
        <Select
          id="profile-language"
          name="language"
          value={language}
          onChange={(event) => setLanguage(event.target.value as Language)}
        >
          {LANGUAGE_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </Select>
      </div>

      <div className="jx-field jx-field--row">
        <label className="jx-label" htmlFor="profile-email-notifications">
          Уведомления на почту
        </label>
        <Switch
          id="profile-email-notifications"
          name="emailNotifications"
          checked={emailNotifications}
          onCheckedChange={setEmailNotifications}
        />
      </div>

      <Button type="submit" variant="primary">
        Сохранить
      </Button>
    </form>
  );
}

